env.NGINX_CONF:
worker_processes 1;
events { worker_connections 1024; }
http {
    map $http_x_forwarded_host $oe_forwarded_host { default $http_x_forwarded_host; '' $http_host; }
    map $http_x_forwarded_proto $oe_forwarded_proto { default $http_x_forwarded_proto; '' $scheme; }
    server {
        listen 443 ssl default;
        server_name __;
        ssl_certificate /etc/nginx/certs/apache-selfsigned.crt;
        ssl_certificate_key /etc/nginx/keys/apache-selfsigned.key;
        proxy_set_header Host $http_host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto $oe_forwarded_proto;
        proxy_set_header X-Forwarded-Host $oe_forwarded_host;
        absolute_redirect off;
        location / { proxy_pass http://frontend; proxy_redirect off; }
        location /api/ { proxy_pass https://oe:8443/api/; proxy_redirect off; }
    }
}
